def audit_diagnostic_ledger_proof_sequence(
    cls, proofs: Any
) -> dict[str, Any]:
    """Audit an ordered sequence of exported diagnostic ledger
    proofs entirely offline, with no access to any ledger.

    ``proofs`` must be a :class:`tuple` of canonical proof strings
    as returned by :meth:`export_diagnostic_ledger_proof`; any other
    container raises :class:`TypeError`, and the empty tuple returns
    a deterministic ``"empty"`` result. The proofs are authenticated
    strictly in sequence order: a non-:class:`str` element raises
    :class:`TypeError`, and an empty string, a non-canonical proof
    or any authentication failure raises :class:`ValueError`. Every
    proof must use the transaction-identity filter mode and request
    the same ordered identity set, or :class:`ValueError` is raised.
    Every proof is fully authenticated before any relation is
    analysed, so a late invalid element never produces a partial
    audit.

    Each adjacent pair forms one hop analysed exactly as
    :meth:`compare_diagnostic_ledger_proofs` analyses a pair, with
    the same boundary, increment and rotation semantics. The hop
    relation is ``"same"`` for equivalent snapshots and
    ``"continued"`` for a legal append or a fully evidenced
    rotation. A first ``"forked"`` hop keeps the common boundary and
    both sides' unique histories and terminates the audit: no later
    hop is inferred. A later proof that is a strict historical
    prefix of the earlier one is ``"rollback"`` (never an ordinary
    fork); a digest, count, time-bound or diagnostic-body
    contradiction at a shared position is ``"rewritten"``; a
    rotation whose connecting segments are missing (the aggregate
    prefix digest never stands in for them) is
    ``"missing_transition"``; and two non-empty proofs with no
    authenticatable common segment are ``"spliced"`` -- except when
    the first proof authenticates the empty ledger. These anomalies
    follow from individually legal proofs, so they are reported in
    the result rather than raised.

    Returns a fresh mapping with ``status``, ``common``, ``hops``
    and ``failure`` in that order. ``status`` is ``"empty"`` for
    the empty tuple, ``"continuous"`` when every hop is ``"same"``
    or ``"continued"``, and ``"failed"`` otherwise. ``hops`` is a
    tuple with one fresh mapping per completed hop, in order, with
    ``index`` (the right-hand proof's position), ``relation``,
    ``common`` (the boundary the hop starts from), ``before_only``
    and ``after_only`` (the sides' unique segments, shaped as
    :meth:`compare_diagnostic_ledger_proofs` returns them),
    ``rotated`` (the identities newly entering the rotated-away
    prefix, in request order) and, on a failing hop, ``reason`` --
    a stable machine-readable classification string. ``failure`` is
    ``None`` for a continuous audit, otherwise a mapping with
    ``index`` (the first failing hop's right-hand position) and
    ``classification`` (``"forked"``, ``"rollback"``,
    ``"rewritten"``, ``"missing_transition"`` or ``"spliced"``);
    ``common`` is then the last boundary every proof up to that
    point jointly authenticated (``None`` from the empty ledger).
    Nested levels never share mutable state with each other or with
    any other call, and the proofs, every ledger, the event graph,
    the business audit and the idempotency state are never modified,
    whether the audit succeeds or raises.
    """
    if not isinstance(proofs, tuple):
        raise TypeError(
            "proofs must be a tuple, got "
            f"{type(proofs).__name__}"
        )
    if not proofs:
        return {
            "status": "empty",
            "common": None,
            "hops": (),
            "failure": None,
        }
    # Authenticate every proof and settle the shared ordered
    # identity set before any relation analysis, so an invalid late
    # element can never leak a partial audit.
    authenticated: list[dict[str, Any]] = []
    first_mode: dict[str, Any] | None = None
    for position, proof in enumerate(proofs):
        auth = cls._authenticate_diagnostic_ledger_proof_auth(
            proof, f"proof at index {position}"
        )
        if first_mode is None:
            first_mode = auth["mode"]
        else:
            cls._require_matching_diagnostic_ledger_proof_identities(
                first_mode, auth["mode"]
            )
        authenticated.append(auth)
    hops: list[dict[str, Any]] = []
    # The last boundary every proof jointly authenticates can never
    # move past the first proof's tail: successful hops only extend
    # history, so a continuous audit ends on that first boundary
    # (None when the first proof authenticates the empty ledger).
    first_common = cls._copy_diagnostic_ledger_proof_boundary(
        cls._diagnostic_ledger_proof_chain_boundary(
            authenticated[0]["view"]
        )
    )

    def common_with_pair(
        pair_boundary: dict[str, Any] | None,
    ) -> dict[str, Any] | None:
        """The last boundary every proof up to a failing hop jointly
        authenticated: the failing pair's boundary when it lies
        before the first proof's tail, otherwise that first
        boundary. ``None`` when the first proof authenticates the
        empty ledger (it authenticates no segments at all) or the
        pair shares no boundary."""
        if first_common is None or pair_boundary is None:
            return None
        if pair_boundary["index"] < first_common["index"]:
            return cls._copy_diagnostic_ledger_proof_boundary(
                pair_boundary
            )
        return cls._copy_diagnostic_ledger_proof_boundary(first_common)

    for right_index in range(1, len(authenticated)):
        before_auth = authenticated[right_index - 1]
        after_auth = authenticated[right_index]
        try:
            relation = cls._diagnostic_ledger_proof_relation(
                before_auth, after_auth
            )
        except ValueError as exc:
            classification = getattr(
                exc, "classification", "rewritten"
            )
            pair_boundary = (
                cls._copy_diagnostic_ledger_proof_boundary(
                    exc.boundary
                )
                if hasattr(exc, "boundary")
                else None
            )
            hops.append(
                {
                    "index": right_index,
                    "relation": classification,
                    "common": pair_boundary,
                    "before_only":
                        cls._copy_diagnostic_ledger_proof_segment_items(
                            cls._diagnostic_ledger_proof_unique_segments(
                                before_auth["view"], pair_boundary
                            )
                        ),
                    "after_only":
                        cls._copy_diagnostic_ledger_proof_segment_items(
                            cls._diagnostic_ledger_proof_unique_segments(
                                after_auth["view"], pair_boundary
                            )
                        ),
                    # The hop never authenticated, so no rotation
                    # across it was ever evidenced.
                    "rotated": (),
                    "reason": classification,
                }
            )
            return {
                "status": "failed",
                "common": common_with_pair(pair_boundary),
                "hops": tuple(hops),
                "failure": {
                    "index": right_index,
                    "classification": classification,
                },
            }
        pair_common = cls._copy_diagnostic_ledger_proof_boundary(
            relation["common"]
        )
        hop = {
            "index": right_index,
            "relation": relation["relation"],
            "common": pair_common,
            "before_only":
                cls._copy_diagnostic_ledger_proof_segment_items(
                    relation["before_only"]
                ),
            "after_only":
                cls._copy_diagnostic_ledger_proof_segment_items(
                    relation["after_only"]
                ),
            "rotated": tuple(relation["rotated"]),
        }
        if relation["relation"] == "forked":
            hop["reason"] = "forked"
        hops.append(hop)
        if relation["relation"] == "forked":
            return {
                "status": "failed",
                "common": common_with_pair(pair_common),
                "hops": tuple(hops),
                "failure": {
                    "index": right_index,
                    "classification": "forked",
                },
            }
    return {
        "status": "continuous",
        "common": cls._copy_diagnostic_ledger_proof_boundary(
            first_common
        ),
        "hops": tuple(hops),
        "failure": None,
    }

@classmethod
def _diagnostic_ledger_proof_unique_segments(
    cls,
    view: dict[str, Any],
    boundary: dict[str, Any] | None,
) -> tuple[dict[str, Any], ...]:
    """The retained segments one side of a hop alone carries after
    the pair's last jointly authenticated ``boundary`` (all of its
    retained segments when the boundary is ``None``)."""
    segments = view["segments"]
    if not segments:
        return ()
    start = segments[0]["index"]
    end = segments[-1]["index"]
    first = start if boundary is None else max(start, boundary["index"] + 1)
    return cls._diagnostic_ledger_proof_segment_items(view, first, end)

@staticmethod
def _copy_diagnostic_ledger_proof_boundary(
    boundary: dict[str, Any] | None,
) -> dict[str, Any] | None:
    """Detached ``index``/``digest``/``entries`` copy of one common
    boundary record, or ``None``."""
    if boundary is None:
        return None
    return {
        "index": boundary["index"],
        "digest": boundary["digest"],
        "entries": boundary["entries"],
    }

@staticmethod
def _copy_diagnostic_ledger_proof_segment_items(
    items: tuple[dict[str, Any], ...],
) -> tuple[dict[str, Any], ...]:
    """Deeply detached copies of the unique-segment records a hop
    carries so nested results of one audit never share mutable
    state with each other or with the authenticated views."""
    detached: list[dict[str, Any]] = []
    for item in items:
        entries: list[dict[str, Any]] = []
        for entry in item["entries"]:
            entries.append(
                {
                    "at": entry["at"],
                    "summary": dict(entry["summary"]),
                    "records": tuple(entry["records"]),
                }
            )
        detached.append(
            {
                "index": item["index"],
                "digest": item["digest"],
                "entries": tuple(entries),
            }
        )
    return tuple(detached)

@classmethod
def _authenticate_diagnostic_ledger_proof_auth(
    cls, proof: Any, side: str = "proof"
) -> dict[str, Any]:
    """Fully authenticate one exported proof string exactly as
    :meth:`verify_diagnostic_ledger_proof` requires and return a
    fresh isolated authentication record bundling its transaction
    filter mode, authenticated snapshot summary, matched items,
    rotated and absent identities, and internal authenticated-history
    view. ``side`` only labels boundary defects in error messages.
    Every defect raises exactly as :meth:`verify_diagnostic_ledger_proof`
    documents: :class:`TypeError` for a non-:class:`str`,
    :class:`ValueError` for an empty, non-canonical or
    non-authenticating proof."""
    mode, snapshot, items, rotated, absent, view = (
        cls._authenticate_diagnostic_ledger_proof_string(proof)
    )
    if (
        mode["mode"]
        != cls._DIAGNOSTIC_LEDGER_PROOF_FILTER_MODE_TRANSACTIONS
    ):
        raise ValueError(
            f"the {side} proof must use the transaction identity "
            "filter mode"
        )
    return {
        "mode": mode,
        "snapshot": snapshot,
        "items": items,
        "rotated": rotated,
        "absent": absent,
        "view": view,
    }

@staticmethod
def _require_matching_diagnostic_ledger_proof_identities(
    before_mode: dict[str, Any], after_mode: dict[str, Any]
) -> None:
    """Require two authenticated transaction-mode proofs to request
    the same ordered transaction identity set; otherwise raise
    :class:`ValueError`."""
    if before_mode["transactions"] != after_mode["transactions"]:
        raise ValueError(
            "both proofs must request the same ordered transaction "
            "identity set"
        )

@classmethod
def _diagnostic_ledger_proof_relation(
    cls,
    before_auth: dict[str, Any],
    after_auth: dict[str, Any],
) -> dict[str, Any]:
    """Align two already authenticated transaction-mode proofs and
    report how the ``after`` history relates to the ``before``
    history. This is the pure offline engine shared by
    :meth:`compare_diagnostic_ledger_proofs` and
    :meth:`audit_diagnostic_ledger_proof_sequence`; every fact comes
    from the two authenticated proof packages and nothing is read
    from or written to the filesystem.

    Returns a fresh ``same``/``continued``/``forked`` relation record
    exactly as :meth:`compare_diagnostic_ledger_proofs` documents.
    Every non-fork divergence -- a strict historical prefix
    (rollback), two non-empty histories with no authenticatable
    common segment (splice), a rotation that ran past the before
    tail without its connecting segments, or a digest, entry-count,
    time-bound, evidence or retained-body contradiction at a shared
    position (rewrite) -- raises :class:`ValueError` carrying a
    stable machine-readable ``classification`` attribute naming the
    relation class (``"rollback"``, ``"spliced"``,
    ``"missing_transition"`` or ``"rewritten"``)."""
    before_snapshot = before_auth["snapshot"]
    after_snapshot = after_auth["snapshot"]
    before_rotated = before_auth["rotated"]
    after_rotated = after_auth["rotated"]
    before_view = before_auth["view"]
    after_view = after_auth["view"]
    b_segments = before_view["segments"]
    a_segments = after_view["segments"]
    b_dropped = before_view["dropped"]
    a_dropped = after_view["dropped"]
    if before_snapshot == after_snapshot:
        return {
            "relation": "same",
            "common": cls._diagnostic_ledger_proof_chain_boundary(
                before_view
            ),
            "before_only": (),
            "after_only": (),
            "rotated": (),
        }
    if not b_segments:
        # The empty ledger has no retained segment and (checked
        # here) no rotated prefix, so there is nothing to align:
        # any non-empty authenticated history continues it.
        if b_dropped is not None:
            raise cls._diagnostic_ledger_proof_relation_error(
                "rewritten",
                "the before proof's rotated-prefix boundary cannot "
                "be located without retained segments",
            )
        if not a_segments:
            raise cls._diagnostic_ledger_proof_relation_error(
                "rewritten",
                "the after proof's rotated-prefix boundary cannot "
                "be located without retained segments",
            )
        return {
            "relation": "continued",
            "common": None,
            "before_only": (),
            "after_only": cls._diagnostic_ledger_proof_segment_items(
                after_view,
                a_segments[0]["index"],
                a_segments[-1]["index"],
            ),
            "rotated": after_rotated,
        }
    b_boundary = cls._diagnostic_ledger_proof_chain_start(
        before_view, "before"
    )
    a_boundary = cls._diagnostic_ledger_proof_chain_start(
        after_view, "after"
    )

    if a_dropped is None:
        if b_dropped is not None:
            raise cls._diagnostic_ledger_proof_relation_error(
                "rewritten",
                "the after proof does not carry the rotated-prefix "
                "continuity proof the before proof established",
                cls._diagnostic_ledger_proof_boundary_if_carried(
                    before_view, b_boundary
                ),
            )
    elif b_dropped is None:
        cls._diagnostic_ledger_proof_prefix_inheritance(
            before_view, a_boundary, a_dropped, after_view["evidence"]
        )
    else:
        if a_boundary < b_boundary:
            raise cls._diagnostic_ledger_proof_relation_error(
                "rewritten",
                "the after proof rotates away less history than "
                "the before proof already rotated away",
                cls._diagnostic_ledger_proof_boundary_if_carried(
                    before_view, a_boundary
                ),
            )
        if a_boundary == b_boundary:
            if (
                a_dropped != b_dropped
                or before_view["evidence"] != after_view["evidence"]
            ):
                raise cls._diagnostic_ledger_proof_relation_error(
                    "rewritten",
                    "the proofs disagree about the rotated-away "
                    "prefix they share",
                    cls._diagnostic_ledger_proof_boundary_if_carried(
                        before_view, b_boundary
                    ),
                )
        else:
            cls._diagnostic_ledger_proof_prefix_inheritance(
                before_view,
                a_boundary,
                a_dropped,
                after_view["evidence"],
            )
    b_start = b_segments[0]["index"]
    b_end = b_segments[-1]["index"]
    a_start = a_segments[0]["index"] if a_segments else 1
    a_end = a_segments[-1]["index"] if a_segments else 0
    divergence: int | None = None
    for position in range(max(b_start, a_start), min(b_end, a_end) + 1):
        if not hmac.compare_digest(
            b_segments[position - b_start]["digest"],
            a_segments[position - a_start]["digest"],
        ):
            divergence = position
            break
    if divergence is not None:
        boundary = divergence - 1
        if boundary >= a_start:
            common = cls._diagnostic_ledger_proof_boundary_at(
                after_view, boundary
            )
        elif a_dropped is not None:
            # The boundary is the verified rotated-prefix boundary
            # segment both sides authenticated.
            common = {
                "index": a_boundary,
                "digest": a_dropped["digest"],
                "entries": a_dropped["entries"],
            }
        else:
            raise cls._diagnostic_ledger_proof_relation_error(
                "spliced",
                "the two proofs share no authenticatable segment "
                "and come from different ledgers",
            )
        return {
            "relation": "forked",
            "common": common,
            "before_only": (
                cls._diagnostic_ledger_proof_segment_items(
                    before_view, divergence, b_end
                )
            ),
            "after_only": cls._diagnostic_ledger_proof_segment_items(
                after_view, divergence, a_end
            ),
            "rotated": (),
        }
    if a_end < b_end:
        # The after history ends inside the before history. Every
        # segment through a_end agreed, so a_end (or the verified
        # rotated-prefix boundary when a rotated after ends before
        # the before retained chain begins) is the last jointly
        # authenticated boundary.
        if a_segments:
            rollback_boundary = (
                cls._diagnostic_ledger_proof_boundary_if_carried(
                    after_view, a_end
                )
            )
        elif a_dropped is not None:
            rollback_boundary = {
                "index": a_boundary,
                "digest": a_dropped["digest"],
                "entries": a_dropped["entries"],
            }
        else:
            rollback_boundary = None
        raise cls._diagnostic_ledger_proof_relation_error(
            "rollback",
            "the after proof is a strict historical prefix of the "
            "before proof (a rollback)",
            rollback_boundary,
        )
    if b_end >= a_start:
        common = cls._diagnostic_ledger_proof_boundary_at(
            before_view, b_end
        )
    else:
        # after rotated away exactly up to the before proof's tail,
        # so the shared boundary is the verified prefix boundary.
        common = {
            "index": a_boundary,
            "digest": a_dropped["digest"],
            "entries": a_dropped["entries"],
        }
    before_rotated_set = set(before_rotated)
    return {
        "relation": "continued",
        "common": common,
        "before_only": (),
        "after_only": cls._diagnostic_ledger_proof_segment_items(
            after_view, max(a_start, b_end + 1), a_end
        ),
        "rotated": tuple(
            identity
            for identity in after_rotated
            if identity not in before_rotated_set
        ),
    }

@staticmethod
def _diagnostic_ledger_proof_relation_error(
    classification: str,
    message: str,
    boundary: dict[str, Any] | None = None,
) -> ValueError:
    """Build the :class:`ValueError` a non-fork relation anomaly
    raises, tagged with a stable machine-readable
    ``classification`` (``"rollback"``, ``"spliced"``,
    ``"missing_transition"`` or ``"rewritten"``) and, when it can be
    located, the detached ``boundary`` record (``index``,
    ``digest`` and cumulative ``entries``) the two sides last
    jointly authenticated before the anomaly; ``None`` marks that no
    such boundary exists."""
    error = ValueError(message)
    error.classification = classification
    error.boundary = boundary
    return error

@classmethod
def _diagnostic_ledger_proof_chain_start(
    cls, view: dict[str, Any], side: str
) -> int:
    """The segment index of the rotated-prefix boundary of one
    authenticated proof view (0 when nothing was rotated away),
    after checking the retained chain starts where the prefix
    proof says it must. A boundary that cannot be located, or a
    retained chain that does not start at the genesis segment
    (without a prefix) or right after the boundary (with one),
    raises :class:`ValueError`."""
    segments = view["segments"]
    dropped = view["dropped"]
    if dropped is None:
        if segments and segments[0]["index"] != 1:
            raise ValueError(
                f"the {side} proof's retained chain does not start "
                "at the genesis segment"
            )
        return 0
    if not segments:
        raise ValueError(
            f"the {side} proof's rotated-prefix boundary cannot "
            "be located without retained segments"
        )
    if segments[0]["index"] < 2:
        raise ValueError(
            f"the {side} proof's rotated-prefix proof covers no "
            "segment"
        )
    return segments[0]["index"] - 1

@classmethod
def _diagnostic_ledger_proof_prefix_inheritance(
    cls,
    before_view: dict[str, Any],
    a_boundary: int,
    a_dropped: dict[str, Any],
    a_evidence: tuple[str, ...],
) -> None:
    """Verify that the ``after`` proof's rotated-away prefix
    exactly inherits the history the ``before`` proof
    authenticated: the boundary segment's digest, the cumulative
    entry count, the prefix time bounds and the prefix evidence's
    identity sequence must equal, position by position, what
    ``before_view`` retains (plus its own already-rotated prefix,
    if any). A rotation that ran past the ``before`` proof's tail
    without the transition segments connecting the two ends raises
    a classified :class:`ValueError` (``"missing_transition"``);
    any digest, count, time-bound or identity contradiction at a
    shared position raises one classified ``"rewritten"``."""
    b_segments = before_view["segments"]
    b_entries = before_view["segment_entries"]
    b_dropped = before_view["dropped"]
    b_start = b_segments[0]["index"]
    b_end = b_segments[-1]["index"]
    first_covered = b_start if b_dropped is not None else 1

    def inherited_boundary(index: int) -> dict[str, Any] | None:
        """The detached boundary record for the segment right
        before segment ``index`` on the before proof's
        authenticated chain when that proof directly carries it;
        ``None`` for the genesis boundary or a segment the proof
        only remembers through its aggregate rotated-prefix
        digest."""
        return cls._diagnostic_ledger_proof_boundary_if_carried(
            before_view, index
        )

    if a_boundary > b_end:
        raise cls._diagnostic_ledger_proof_relation_error(
            "missing_transition",
            "the after proof rotated away history past the before "
            "proof's tail and the transition segments connecting "
            "the two ends are missing",
            inherited_boundary(b_end),
        )
    covered: list[int] = []
    for position in range(first_covered, a_boundary + 1):
        if position < b_start:
            raise cls._diagnostic_ledger_proof_relation_error(
                "missing_transition",
                "the after proof rotated away segments the before "
                "proof does not carry and the transition segments "
                "connecting the two ends are missing",
                inherited_boundary(b_start - 1),
            )
        covered.append(position - b_start)
    boundary_meta = b_segments[covered[-1]]
    prior_boundary = inherited_boundary(a_boundary - 1)
    if not hmac.compare_digest(
        boundary_meta["digest"], a_dropped["digest"]
    ):
        raise cls._diagnostic_ledger_proof_relation_error(
            "rewritten",
            "the after proof's rotated-prefix digest contradicts "
            "the before proof's retained segment at the boundary",
            prior_boundary,
        )
    entries = sum(b_segments[offset]["entries"] for offset in covered)
    if b_dropped is not None:
        entries += b_dropped["entries"]
    if entries != a_dropped["entries"]:
        raise cls._diagnostic_ledger_proof_relation_error(
            "rewritten",
            "the after proof's rotated-prefix entry count "
            "contradicts the before proof's retained segments",
            prior_boundary,
        )
    first_at = (
        b_segments[covered[0]]["first_at"]
        if b_dropped is None
        else b_dropped["first_at"]
    )
    if first_at != a_dropped["first_at"]:
        raise cls._diagnostic_ledger_proof_relation_error(
            "rewritten",
            "the after proof's rotated-prefix time bounds "
            "contradict the before proof's retained segments",
            prior_boundary,
        )
    if boundary_meta["last_at"] != a_dropped["last_at"]:
        raise cls._diagnostic_ledger_proof_relation_error(
            "rewritten",
            "the after proof's rotated-prefix time bounds "
            "contradict the before proof's retained segments",
            prior_boundary,
        )
    new_identities: list[str] = []
    for offset in covered:
        for entry in b_entries[offset]:
            new_identities.append(entry["summary"]["transaction"])
    if (
        tuple(before_view["evidence"]) + tuple(new_identities)
        != a_evidence
    ):
        raise cls._diagnostic_ledger_proof_relation_error(
            "rewritten",
            "the after proof's prefix evidence does not exactly "
            "inherit the before proof's history",
            prior_boundary,
        )

@classmethod
def _diagnostic_ledger_proof_boundary_at(
    cls, view: dict[str, Any], index: int
) -> dict[str, Any]:
    """The common-boundary record (``index``, ``digest`` and
    cumulative ``entries`` count) for the retained segment at
    segment number ``index`` of one authenticated proof view."""
    segments = view["segments"]
    dropped = view["dropped"]
    entries = 0 if dropped is None else dropped["entries"]
    meta: dict[str, Any] | None = None
    for candidate in segments:
        if candidate["index"] > index:
            break
        entries += candidate["entries"]
        meta = candidate
    assert meta is not None and meta["index"] == index
    return {
        "index": index,
        "digest": meta["digest"],
        "entries": entries,
    }

@classmethod
def _diagnostic_ledger_proof_boundary_if_carried(
    cls, view: dict[str, Any], index: int
) -> dict[str, Any] | None:
    """The boundary record at segment number ``index`` when the
    proof directly authenticates that segment: a retained segment,
    the segment ending its verified rotated-away prefix (its first
    retained segment's predecessor), or the genesis boundary
    (``None``) when ``index`` is 0. For any other segment the proof
    only remembers through an aggregate prefix digest, the exact
    boundary cannot be reconstructed, so ``None`` is returned rather
    than guessing."""
    if index <= 0:
        return None
    segments = view["segments"]
    dropped = view["dropped"]
    if not segments:
        return None
    start = segments[0]["index"]
    end = segments[-1]["index"]
    if start <= index <= end:
        return cls._diagnostic_ledger_proof_boundary_at(view, index)
    if dropped is not None and index == start - 1:
        return {
            "index": index,
            "digest": dropped["digest"],
            "entries": dropped["entries"],
        }
    return None

@classmethod
def _diagnostic_ledger_proof_chain_boundary(
    cls, view: dict[str, Any]
) -> dict[str, Any] | None:
    """The common-boundary record for the tail of one
    authenticated proof view's chain, or ``None`` for the empty
    ledger."""
    segments = view["segments"]
    if not segments:
        return None
    return cls._diagnostic_ledger_proof_boundary_at(
        view, segments[-1]["index"]
    )

@classmethod
def _diagnostic_ledger_proof_segment_items(
    cls, view: dict[str, Any], first: int, last: int
) -> tuple[dict[str, Any], ...]:
    """One fresh ``index``/``digest``/``entries`` mapping per
    retained segment of ``view`` with a segment number in the
    inclusive ``first``..``last`` range, in chain order; an empty
    range yields an empty tuple."""
    if first > last:
        return ()
    segments = view["segments"]
    segment_entries = view["segment_entries"]
    start = segments[0]["index"]
    items: list[dict[str, Any]] = []
    for position in range(first, last + 1):
        offset = position - start
        meta = segments[offset]
        items.append(
            {
                "index": meta["index"],
                "digest": meta["digest"],
                "entries": segment_entries[offset],
            }
        )
    return tuple(items)

@classmethod
def _publish_caches_recovery_locked(
    cls,
    index_path: str,
    index_tmp: str,
    progress_path: str,
    progress_tmp: str | None,
    recovery_path: str,
) -> None:
    """Publish the new caches under the cross-process recovery
    protocol. The caller holds the chain lock and has already
    flushed and fsync-ed every temp file; this routine owns the
    durable publication sequence and cleanup.

def _parse_diagnostic_ledger_proof(
    cls, document: Any, proof: str
) -> None:
    """Validate the proof envelope's top-level shape, format,
    version and checksum field. The checksum itself is verified last
    by the caller once the package content has authenticated. Any
    defect raises :class:`ValueError`."""
    if proof.startswith("\ufeff"):
        raise ValueError("proof must be UTF-8 without a BOM")
    if proof.endswith("\n") or proof.endswith("\r"):
        raise ValueError("proof must not have a trailing newline")
    if not isinstance(document, dict) or set(document) != set(
        cls._DIAGNOSTIC_LEDGER_PROOF_KEYS
    ):
        raise ValueError("proof has bad top-level keys")
    if document["format"] != cls._DIAGNOSTIC_LEDGER_PROOF_FORMAT:
        raise ValueError("proof has an unknown format")
    version = document["version"]
    if (
        isinstance(version, bool)
        or not isinstance(version, int)
        or version
        not in cls._DIAGNOSTIC_LEDGER_PROOF_SUPPORTED_VERSIONS
    ):
        raise ValueError("proof has an unsupported version")
    checksum = document["checksum"]
    if (
        not isinstance(checksum, str)
        or len(checksum) != 64
        or set(checksum) - cls._HEX_DIGITS
    ):
        raise ValueError("proof checksum is malformed")
    snapshot = document["snapshot"]
    if not isinstance(snapshot, dict) or set(snapshot) != set(
        cls._DIAGNOSTIC_LEDGER_PROOF_SNAPSHOT_KEYS
    ):
        raise ValueError("proof snapshot has bad keys")

@classmethod
def _authenticate_diagnostic_ledger_proof(
    cls, document: dict[str, Any], mode: dict[str, Any]
) -> tuple[
    dict[str, Any],
    tuple[dict[str, Any], ...],
    tuple[str, ...],
    tuple[str, ...],
    dict[str, Any],
]:
    """Recompute every fact a proof claims from its embedded
    manifest, prefix evidence and required segment bodies and return
    ``(snapshot, items, rotated, absent, view)``. The caller has
    already validated the envelope and the package checksum is
    verified after this returns. Any inconsistency raises
    :class:`ValueError`; no partial result is produced.

    ``view`` is an internal fresh mapping with the authenticated
    history the proof binds: ``segments`` (one fresh metadata
    mapping per retained segment, in chain order), ``dropped`` (the
    rotated-prefix continuity proof, or ``None``), ``evidence`` (the
    rotated-away transaction identities in prefix order) and
    ``segment_entries`` (one tuple per retained segment, in chain
    order, of fresh ``at``/``summary``/``records`` entry mappings,
    or ``None`` for a segment whose body the filter did not
    require). It shares nothing with the proof document."""
    manifest_object = document["manifest"]
    if not isinstance(manifest_object, dict):
        raise ValueError("proof manifest must be an object")
    manifest_raw = cls._canonical_json(manifest_object).encode("utf-8")
    segments, dropped, evidence_ref, manifest_digest = (
        cls._parse_diagnostic_ledger_manifest(manifest_raw)
    )
    # Reconstruct the digest chain from the manifest's ordered
    # digests: the manifest is the published snapshot record and its
    # checksum covers this ordering. Every embedded body then proves
    # its own link against the same predecessor.
    expected_previous: dict[str, str] = {}
    previous_digest = (
        cls._DIAGNOSTIC_LEDGER_GENESIS_PREV
        if dropped is None
        else dropped["digest"]
    )
    for meta in segments:
        expected_previous[meta["name"]] = previous_digest
        previous_digest = meta["digest"]
    evidence_object = document["evidence"]
    evidence_digest: str | None = None
    evidence_transactions: set[str] = set()
    evidence_identities: tuple[str, ...] = ()
    if dropped is None:
        if evidence_object is not None:
            raise ValueError(
                "proof carries prefix evidence without a dropped "
                "prefix"
            )
    else:
        if not isinstance(evidence_object, dict):
            raise ValueError(
                "proof is missing its rotated-prefix evidence"
            )
        if evidence_ref is None:
            raise ValueError(
                "proof manifest dropped proof and evidence disagree"
            )
        evidence_raw = cls._canonical_json(
            evidence_object
        ).encode("utf-8")
        evidence_digest = hashlib.sha256(evidence_raw).hexdigest()
        if not hmac.compare_digest(
            evidence_digest, evidence_ref["digest"]
        ):
            raise ValueError(
                "proof prefix evidence digest does not match the "
                "manifest"
            )
        evidence = cls._parse_diagnostic_ledger_evidence(
            evidence_raw
        )
        if (
            evidence["digest"] != dropped["digest"]
            or evidence["entries"] != dropped["entries"]
            or evidence["first_at"] != dropped["first_at"]
            or evidence["last_at"] != dropped["last_at"]
        ):
            raise ValueError(
                "proof prefix evidence does not match the dropped "
                "prefix"
            )
        evidence_transactions = set(evidence["transactions"])
        evidence_identities = evidence["transactions"]
    required_names = (
        cls._required_diagnostic_ledger_proof_segments(segments, mode)
    )
    raw_embedded = document["segments"]
    if not isinstance(raw_embedded, list):
        raise ValueError("proof segments must be a list")
    metas_by_name = {meta["name"]: meta for meta in segments}
    embedded: dict[str, tuple[int, str, list[
        tuple[int, tuple[str, ...]]
    ]]] = {}
    for entry in raw_embedded:
        if not isinstance(entry, dict) or set(entry) != set(
            cls._DIAGNOSTIC_LEDGER_PROOF_SEGMENT_KEYS
        ):
            raise ValueError("proof segment entry has bad keys")
        name = entry["name"]
        if (
            not isinstance(name, str)
            or name not in metas_by_name
            or name in embedded
        ):
            raise ValueError("proof segment name is malformed")
        segment_document = entry["document"]
        if not isinstance(segment_document, dict):
            raise ValueError("proof segment document must be an object")
        segment_raw = cls._canonical_json(
            segment_document
        ).encode("utf-8")
        index, prev, pairs, digest = (
            cls._parse_diagnostic_ledger_segment(segment_raw)
        )
        meta = metas_by_name[name]
        if index != meta["index"]:
            raise ValueError(
                "proof segment index does not match the manifest"
            )
        if not hmac.compare_digest(digest, meta["digest"]):
            raise ValueError(
                "proof segment digest does not match the manifest"
            )
        if not hmac.compare_digest(prev, expected_previous[name]):
            raise ValueError("proof segment digest chain is broken")
        if len(pairs) != meta["entries"]:
            raise ValueError(
                "proof segment entry count does not match the manifest"
            )
        if (
            pairs[0][0] != meta["first_at"]
            or pairs[-1][0] != meta["last_at"]
        ):
            raise ValueError(
                "proof segment time bounds do not match the manifest"
            )
        embedded[name] = (index, prev, pairs)
    if set(embedded) != set(required_names):
        raise ValueError(
            "proof does not carry exactly the segments required by "
            "its filter"
        )
    # Splice the embedded bodies back together in manifest order and
    # authenticate the embedded chains, their per-segment canonical
    # ordering, non-decreasing times across embedded boundaries and
    # their disjointness from the remembered prefix identities.
    all_pairs: list[tuple[int, tuple[str, ...]]] = []
    previous_at: int | None = None
    for meta in segments:
        if meta["name"] not in embedded:
            previous_at = None
            continue
        _index, _prev, pairs = embedded[meta["name"]]
        if previous_at is not None and pairs[0][0] < previous_at:
            raise ValueError(
                "proof segments are not in time order"
            )
        all_pairs.extend(pairs)
        previous_at = pairs[-1][0]
    chains = tuple(chain for _at, chain in all_pairs)
    summaries = cls._authenticate_recovery_diagnostic_chains(chains)
    offset = 0
    for meta in segments:
        if meta["name"] not in embedded:
            continue
        _index, _prev, pairs = embedded[meta["name"]]
        keys = [
            (at, summaries[offset + position]["transaction"])
            for position, (at, _chain) in enumerate(pairs)
        ]
        if keys != sorted(keys):
            raise ValueError(
                "proof segment entries are not in canonical order"
            )
        offset += len(pairs)
    retained_transactions = {
        summary["transaction"] for summary in summaries
    }
    if retained_transactions & evidence_transactions:
        raise ValueError(
            "proof prefix evidence repeats a retained transaction"
        )
    if (
        mode["mode"] == cls._DIAGNOSTIC_LEDGER_PROOF_FILTER_MODE_TIME
        and cls._diagnostic_ledger_proof_range_meets_dropped(
            dropped, mode["start"], mode["end"]
        )
    ):
        raise ValueError(
            "proof time range intersects the rotated-away prefix, "
            "whose per-entry times are not recoverable"
        )
    items = cls._diagnostic_ledger_proof_items(
        all_pairs, summaries, mode
    )
    rotated: tuple[str, ...] = ()
    absent: tuple[str, ...] = ()
    if (
        mode["mode"]
        == cls._DIAGNOSTIC_LEDGER_PROOF_FILTER_MODE_TRANSACTIONS
    ):
        items_by_transaction: dict[str, int] = {}
        for item in items:
            identity = item["summary"]["transaction"]
            if identity in items_by_transaction:
                raise ValueError(
                    "one transaction identity is classified as "
                    "retained more than once"
                )
            items_by_transaction[identity] = 1
        rotated_identities: list[str] = []
        absent_identities: list[str] = []
        for identity in mode["transactions"]:
            classes = (
                identity in items_by_transaction,
                identity in evidence_transactions,
            )
            if sum(classes) > 1:
                raise ValueError(
                    "one transaction identity falls into more than "
                    "one classification"
                )
            if classes[0]:
                continue
            if classes[1]:
                rotated_identities.append(identity)
            else:
                absent_identities.append(identity)
        rotated = tuple(rotated_identities)
        absent = tuple(absent_identities)
    snapshot = cls._diagnostic_ledger_proof_snapshot(
        manifest_raw,
        manifest_object,
        segments,
        evidence_digest,
    )
    if snapshot != document["snapshot"]:
        raise ValueError("proof snapshot does not match its manifest")
    segment_entries: list[tuple[dict[str, Any], ...] | None] = []
    offset = 0
    for meta in segments:
        embedded_entry = embedded.get(meta["name"])
        if embedded_entry is None:
            segment_entries.append(None)
            continue
        _index, _prev, pairs = embedded_entry
        segment_entries.append(
            tuple(
                {
                    "at": pairs[position][0],
                    "summary": dict(summaries[offset + position]),
                    "records": pairs[position][1],
                }
                for position in range(len(pairs))
            )
        )
        offset += len(pairs)
    view = {
        "segments": [dict(meta) for meta in segments],
        "dropped": None if dropped is None else dict(dropped),
        "evidence": evidence_identities,
        "segment_entries": tuple(segment_entries),
    }
    return dict(snapshot), items, rotated, absent, view

