@classmethod
def _proof_audit_checkpoint_verify_state(
    cls,
    status: str,
    hops: list[dict[str, Any]],
    audit_common: dict[str, Any] | None,
    last_auth: dict[str, Any],
) -> None:
    """Cross-field consistency of an authenticated non-empty
    checkpoint: the recorded common boundary, the terminal hop and
    the cumulative rotated identities must agree with the
    re-authenticated last-proof view. Any contradiction raises
    :class:`ValueError`.

    Only the last proof's view is retained, so the terminal hop is
    the point fully anchored to it: its pair boundary must match the
    view when the view carries that segment, and its
    ``after_only`` side must equal exactly the segments the view
    uniquely carries past that boundary. Earlier hops (and the
    first-proof tail they pin) are bound by the checksum and the
    structural checks; the audit-level common boundary is derived
    from them."""
    view = last_auth["view"]
    tail = cls._diagnostic_ledger_proof_chain_boundary(view)
    if not hops:
        if status != "continuous":
            raise ValueError(
                "a single-proof checkpoint must be continuous"
            )
        if audit_common != tail:
            raise ValueError(
                "checkpoint common boundary is not the single "
                "proof's tail"
            )
