@classmethod
def _proof_audit_checkpoint_verify_state(
    cls,
    status: str,
    hops: list[dict[str, Any]],
    audit_common: dict[str, Any] | None,
    last_auth: dict[str, Any],
) -> None:
    """Cross-field consistency of an authenticated non-empty
    checkpoint: the recorded common boundary, the terminal hop and
    the cumulative rotated identities must agree with the
    re-authenticated last-proof view. Any contradiction raises
    :class:`ValueError`.

    Only the last proof's view is retained, so the terminal hop is
    the point fully anchored to it: its pair boundary must match the
    view when the view carries that segment, and its
    ``after_only`` side must equal exactly the segments the view
    uniquely carries past that boundary. Earlier hops (and the
    first-proof tail they pin) are bound by the checksum and the
    structural checks; the audit-level common boundary is derived
    from them."""
    view = last_auth["view"]
    tail = cls._diagnostic_ledger_proof_chain_boundary(view)
    if not hops:
        if status != "continuous":
            raise ValueError(
                "a single-proof checkpoint must be continuous"
            )
        if audit_common != tail:
            raise ValueError(
                "checkpoint common boundary is not the single "
                "proof's tail"
            )
        return
    terminal_hop = hops[-1]
    hop_boundary = terminal_hop["common"]
    if hop_boundary is not None and view["segments"]:
        located = cls._diagnostic_ledger_proof_boundary_if_carried(
            view, hop_boundary["index"]
        )
        if located is not None and located != hop_boundary:
            raise ValueError(
                "checkpoint terminal hop boundary does not match "
                "the last proof view"
            )
    expected_after = (
        cls._diagnostic_ledger_proof_unique_segments(
            view, hop_boundary
        )
    )
    expected_items = cls._copy_diagnostic_ledger_proof_segment_items(
        expected_after
    )
    if expected_items != terminal_hop["after_only"]:
        raise ValueError(
            "checkpoint terminal hop unique segments do not match "
            "the last proof view"
        )
    cumulative_rotated = tuple(last_auth["rotated"])
    for hop in hops:
        relation = hop["relation"]
        if relation == "same":
            if hop["rotated"]:
                raise ValueError(
                    "a same hop cannot rotate identities away"
                )
        elif relation == "continued":
            cls._proof_audit_checkpoint_require_rotated_subsequence(
                cumulative_rotated, hop["rotated"]
            )
        elif hop is not terminal_hop:
            raise ValueError(
                "a failing classification is only allowed on the "
                "terminal hop"
            )
    if status == "continuous":
        # The first same/continued hop starts exactly at the first
        # proof's tail, which the audit common never moves past.
        if audit_common != hops[0]["common"]:
            raise ValueError(
                "checkpoint common boundary does not match the "
                "first hop"
            )
        return
    if terminal_hop["rotated"]:
        raise ValueError(
            "a failed hop cannot evidence rotation across it"
        )
    if len(hops) == 1:
        if hop_boundary is None and audit_common is not None:
            raise ValueError(
                "checkpoint common boundary must be absent when the "
                "only hop shares no boundary"
            )
    else:
        first_common = hops[0]["common"]
        derived_common = cls._proof_audit_common_with_pair(
            first_common, hop_boundary
        )
        if audit_common != derived_common:
            raise ValueError(
                "checkpoint common boundary does not follow from "
                "its hops"
            )

@staticmethod
def _proof_audit_checkpoint_require_rotated_subsequence(
    cumulative_rotated: tuple[str, ...],
    hop_rotated: tuple[str, ...],
) -> None:
    """Require the identities newly rotated across one hop to be
    exactly the hop's members within the last proof's cumulative
    rotated-away tuple, in request order (they remain rotated away
    forever, so they must all survive there)."""
    hop_set = set(hop_rotated)
    if len(hop_set) != len(hop_rotated):
        raise ValueError(
            "checkpoint hop rotates a repeated identity"
        )
    surviving = tuple(
        identity
        for identity in cumulative_rotated
        if identity in hop_set
    )
    if surviving != tuple(hop_rotated):
        raise ValueError(
            "checkpoint hop rotated identities do not match the "
            "last proof's cumulative rotated prefix"
        )

