        script = (
            "import os, json, pickle, sys\n"
            "from city_twin.branches import BranchStore\n"
            "checkpoint, proof = pickle.loads("
            "bytes.fromhex(os.environ['CP_ARGS']))\n"
            "result = BranchStore.resume_proof_audit("
            "checkpoint, (proof,))\n"
