        self.append(left, self.entries[4:6], digest)
        other = tuple(
            (time, make_chain(transaction(100 + time)))
            for time in (5, 6)
        )
        self.append(right, other, digest)
        checkpoint = (
            BranchStore.create_proof_audit_checkpoint(
                (self.export(left), self.export(right))
            )
        )
