@classmethod
def _proof_audit_checkpoint_verify_hop_chain(
    cls,
    status: str,
    hops: list[dict[str, Any]],
    view: dict[str, Any],
) -> None:
    """Verify the completed hops form one contiguous segment digest
    chain anchored on the last proof: a ``"continued"`` hop must
    carry exactly the contiguous segments extending its pair
    boundary (digest and cumulative entry counts included), the end
    of each hop must equal the next hop's pair boundary, and the
    chain must finish on the last proof's tail. ``"same"`` hops add
    no segment and keep the boundary; the terminal anomalous hop
    only has to be reached by the chain ending on its pair
    boundary. Segments rotated away before the last proof's own
    verified prefix boundary are covered by the checksum and the
    chain links, never guessed."""

    def end_boundary(
        hop: dict[str, Any], label: str
    ) -> dict[str, Any] | None:
        """The boundary at the end of one same/continued hop,
        rebuilt from its pair boundary and unique segments."""
        relation = hop["relation"]
        common = hop["common"]
        if relation == "same":
            if hop["after_only"]:
                raise ValueError(
                    f"checkpoint {label} same hop carries unique "
                    "segments"
                )
            return common
        if relation != "continued":
            return common
        if common is None:
            expected_index = 1
            cumulative = 0
        else:
            expected_index = common["index"] + 1
            cumulative = common["entries"]
        end = common
        for item in hop["after_only"]:
            if item["index"] != expected_index:
                raise ValueError(
                    f"checkpoint {label} unique segments are not "
                    "contiguous with its pair boundary"
                )
            cumulative += len(item["entries"])
            end = {
                "index": item["index"],
                "digest": item["digest"],
                "entries": cumulative,
            }
            expected_index += 1
        if end is None:
            raise ValueError(
                f"checkpoint {label} continued hop adds no history"
            )
        return end

    last_position = len(hops) - 1
    for position, hop in enumerate(hops):
        label = f"hop {position}"
        if (
            hop["relation"]
            not in
            cls._PROOF_AUDIT_CHECKPOINT_CONTINUED_RELATIONS
        ):
            if position != last_position:
                raise ValueError(
                    "a failing classification is only allowed on "
                    "the terminal hop"
                )
            continue
        end = end_boundary(hop, label)
        if position == last_position:
            if status != "continuous":
                continue
            tail = cls._diagnostic_ledger_proof_chain_boundary(view)
            if end != tail:
                raise ValueError(
                    "checkpoint hop chain does not finish on the "
                    "last proof tail"
                )
            continue
        next_common = hops[position + 1]["common"]
        if end != next_common:
            raise ValueError(
                "checkpoint hop chain is broken between adjacent "
                "hops"
            )

