def walk(obj, path=()):
    if isinstance(obj, dict):
        for k in list(obj): yield from walk(obj[k], path+(k,))
    elif isinstance(obj, list):
        for i,v in enumerate(obj): yield from walk(v, path+(i,))
    else:
