    chained and its embedded diagnostic chains re-authenticated, and
    a carried segment the last proof still retains must equal that
    proof's segment byte for byte. The successful hops'
    ``after_only`` runs must form one contiguous trunk rooted at the
    first hop boundary (the genesis anchor when the first proof is
    the empty ledger with no rotation), walking -- where the last
    proof rotated history away -- straight onto its verified
    rotated-prefix boundary (digest, time bound), and otherwise
    ending on its authenticated tail. Hop pair boundaries are
    checked against the chain state at their segment. Only a prefix
    the last proof itself remembers solely in aggregate (and the
    fork/rollback leg of the terminal anomalous hop, chained from
    the shared boundary) lies outside this anchoring. Any
    contradiction raises :class:`ValueError`."""
    segments = view["segments"]
    retained = {
        meta["index"]: (meta, view["segment_entries"][position])
        for position, meta in enumerate(segments)
    }
    dropped = view["dropped"]
    terminal_position = len(hops) - 1

    trunk: dict[int, dict[str, Any]] = {}
    for position, hop in enumerate(hops):
        label = f"hop {position}"
        cls._proof_audit_checkpoint_require_ordered_items(
            hop["before_only"], f"{label} before_only"
        )
        cls._proof_audit_checkpoint_require_ordered_items(
            hop["after_only"], f"{label} after_only"
        )
        terminal_failed = (
            position == terminal_position
            and hop["relation"]
            not in
            cls._PROOF_AUDIT_CHECKPOINT_CONTINUED_RELATIONS
        )
        if terminal_failed:
            continue
        if hop["relation"] == "continued" and not hop["after_only"]:
            raise ValueError(
                f"checkpoint {label} continued hop adds no history"
            )
        for item in hop["after_only"]:
            index = item["index"]
            if index in trunk:
                raise ValueError(
                    f"checkpoint {label} repeats a carried segment"
                )
            trunk[index] = item

    expected_boundaries: dict[int, dict[str, Any]] = {}
    for hop in hops:
        common = hop["common"]
        if common is None:
            continue
        existing = expected_boundaries.get(common["index"])
        if existing is not None and existing != common:
            raise ValueError(
                "checkpoint hop boundaries disagree at one segment"
            )
        expected_boundaries[common["index"]] = common

    if trunk:
        indices = sorted(trunk)
        first_common = hops[0]["common"]
        if first_common is None:
            # Growing out of the empty ledger: the first carried
            # segment may sit behind an aggregate rotated prefix no
            # proof in the sequence retained, so its predecessor
            # digest alone cannot be anchored here.
            previous_digest: str | None = None
            cumulative_entries: int | None = None
        else:
            if indices[0] != first_common["index"] + 1:
                raise ValueError(
                    "checkpoint hop history does not start at the "
                    "first hop boundary"
                )
            previous_digest = first_common["digest"]
            cumulative_entries = first_common["entries"]
        expected_index = indices[0]
        last_item: dict[str, Any] | None = None
        for index in indices:
            item = trunk[index]
            if index != expected_index:
                raise ValueError(
                    "checkpoint carried history has a gap or overlap"
                )
            label = f"carried segment {index}"
            if previous_digest is None:
                cls._proof_audit_checkpoint_authenticate_item_bodies(
                    item, label
                )
            else:
                cls._proof_audit_checkpoint_authenticate_item(
                    item, previous_digest, label
                )
            cumulative_entries = (
                len(item["entries"])
                if cumulative_entries is None
                else cumulative_entries + len(item["entries"])
            )
            if index in retained:
                meta, entries = retained[index]
                if item["digest"] != meta["digest"]:
                    raise ValueError(
                        f"checkpoint {label} digest does not match "
                        "the last proof view"
                    )
                if tuple(item["entries"]) != tuple(entries):
                    raise ValueError(
                        f"checkpoint {label} entries do not match "
                        "the last proof view"
                    )
            boundary = expected_boundaries.get(index)
            if boundary is not None:
                if boundary["digest"] != item["digest"]:
                    raise ValueError(
                        f"checkpoint {label} boundary digest does "
                        "not match the carried chain"
                    )
                if (
                    cumulative_entries is not None
                    and boundary["entries"] != cumulative_entries
                ):
                    raise ValueError(
                        f"checkpoint {label} boundary entry count "
                        "does not match the carried chain"
                    )
            previous_digest = item["digest"]
            last_item = item
            expected_index += 1
        cls._proof_audit_checkpoint_reconcile_trunk_end(
            status,
            hops,
            first_common,
            indices,
            last_item,
            cumulative_entries,
            view,
        )
    elif status == "continuous":
        # Only "same" hops: the first hop boundary is already the
        # tail and must be carried by the last view.
        common = hops[0]["common"]
        if common is not None:
            cls._proof_audit_checkpoint_require_view_boundary(
                view, common
            )

    terminal_hop = hops[-1]
    if (
        terminal_hop["relation"]
        not in
        cls._PROOF_AUDIT_CHECKPOINT_CONTINUED_RELATIONS
    ):
        cls._proof_audit_checkpoint_authenticate_failed_leg(
            terminal_hop
        )

@classmethod
def _proof_audit_checkpoint_reconcile_trunk_end(
    cls,
    status: str,
    hops: list[dict[str, Any]],
    first_common: dict[str, Any] | None,
    indices: list[int],
    last_item: dict[str, Any],
    cumulative_entries: int | None,
    view: dict[str, Any],
) -> None:
    """Verify the carried trunk's final boundary against the last
    proof's tail (continuous audits) or its terminal hop boundary /
    rotated-prefix boundary."""
    dropped = view["dropped"]
    tail = cls._diagnostic_ledger_proof_chain_boundary(view)
    terminal_hop = hops[-1]
    terminal_failed = (
        terminal_hop["relation"]
        not in
        cls._PROOF_AUDIT_CHECKPOINT_CONTINUED_RELATIONS
    )
    last_index = indices[-1]
    if status == "continuous":
        assert tail is not None
        if last_index != tail["index"]:
            raise ValueError(
                "checkpoint carried history does not finish on the "
                "last proof tail"
            )
        if last_item["digest"] != tail["digest"]:
            raise ValueError(
                "checkpoint carried history digest does not finish "
                "on the last proof tail"
            )
        if (
            cumulative_entries is not None
            and cumulative_entries != tail["entries"]
        ):
            raise ValueError(
                "checkpoint carried history entry count does not "
                "finish on the last proof tail"
            )
        if dropped is not None:
            if last_item["entries"][-1]["at"] != dropped["last_at"]:
                raise ValueError(
                    "checkpoint carried history time bound does not "
                    "finish on the last proof tail"
                )
        return
    terminal_common = terminal_hop["common"]
    if terminal_common is None:
        # Rollback to the empty ledger (or a failure reached from
        # the empty ledger): nothing retained to reconcile.
        return
    boundary_index = terminal_common["index"]
    if last_index < boundary_index:
        raise ValueError(
            "checkpoint carried history does not reach its terminal "
            "hop boundary"
        )
    if last_index > boundary_index and (
        dropped is None or boundary_index > dropped["index"]
    ):
        raise ValueError(
            "checkpoint carried history runs past its terminal hop "
            "boundary"
        )
    if dropped is not None and last_index == dropped["index"]:
        if last_item["digest"] != dropped["digest"]:
            raise ValueError(
                "checkpoint carried history does not land on the "
                "last proof's rotated-prefix boundary"
            )
        if (
            cumulative_entries is not None
            and cumulative_entries != dropped["entries"]
        ):
            raise ValueError(
                "checkpoint carried history entry count does not "
                "land on the rotated-prefix boundary"
            )
        if last_item["entries"][-1]["at"] != dropped["last_at"]:
            raise ValueError(
                "checkpoint carried history time bound does not "
                "land on the rotated-prefix boundary"
            )

@classmethod
def _proof_audit_checkpoint_require_view_boundary(
    cls, view: dict[str, Any], boundary: dict[str, Any]
) -> None:
    """Require a boundary record to equal a segment the last proof
    directly authenticates."""
    located = cls._diagnostic_ledger_proof_boundary_if_carried(
        view, boundary["index"]
    )
    if located is None or located != boundary:
        raise ValueError(
            "checkpoint hop boundary does not match the last proof "
            "view"
        )

@classmethod
def _proof_audit_checkpoint_authenticate_failed_leg(
    cls, terminal_hop: dict[str, Any]
) -> None:
    """Authenticate the terminal anomalous hop's non-trunk leg:
    fork left or rollback history, chained from the shared pair
    boundary (the genesis anchor when the boundary is absent). The
    after-leg itself is anchored against the last view by the
    caller's unique-segment comparison."""
    common = terminal_hop["common"]
    previous_digest = (
        cls._DIAGNOSTIC_LEDGER_GENESIS_PREV
        if common is None
        else common["digest"]
    )
    for item in terminal_hop["before_only"]:
        cls._proof_audit_checkpoint_authenticate_item(
            item,
            previous_digest,
            f"terminal {terminal_hop['relation']} leg",
        )
        previous_digest = item["digest"]

@classmethod
def _proof_audit_checkpoint_authenticate_item_bodies(
    cls, item: dict[str, Any], label: str
) -> None:
    """Authenticate one carried segment's embedded diagnostic
    chains and stored summaries without a predecessor anchor (used
    solely for the first segment behind an aggregate rotated
    prefix no retained proof remembers)."""
    chains = tuple(
        tuple(entry["records"]) for entry in item["entries"]
    )
    summaries = cls._authenticate_recovery_diagnostic_chains(chains)
    cls._proof_audit_checkpoint_check_item_summaries(
        item, summaries, label
    )

@classmethod
def _proof_audit_checkpoint_authenticate_item(
    cls, item: dict[str, Any], previous_digest: str, label: str
) -> None:
    """Rebuild one carried segment from its recorded entries,
    recompute its digest and predecessor link, re-authenticate its
    embedded diagnostic chains and verify every stored summary."""
    pairs = [
        (entry["at"], tuple(entry["records"]))
        for entry in item["entries"]
    ]
    raw = cls._diagnostic_ledger_segment_document(
        item["index"], previous_digest, pairs
    )
    if not hmac.compare_digest(
        hashlib.sha256(raw).hexdigest(), item["digest"]
    ):
        raise ValueError(
            f"checkpoint {label} digest does not authenticate its "
            "recorded entries"
        )
    index, _prev, parsed_pairs, _digest = (
        cls._parse_diagnostic_ledger_segment(raw)
    )
    if index != item["index"]:
        raise ValueError(
            f"checkpoint {label} index does not authenticate"
        )
    chains = tuple(chain for _at, chain in parsed_pairs)
    summaries = cls._authenticate_recovery_diagnostic_chains(chains)
    keys = [
        (at, summary["transaction"])
        for (at, _chain), summary in zip(parsed_pairs, summaries)
    ]
    if keys != sorted(keys):
        raise ValueError(
            f"checkpoint {label} entries are not in canonical order"
        )
    cls._proof_audit_checkpoint_check_item_summaries(
        item, summaries, label
    )

@classmethod
def _proof_audit_checkpoint_check_item_summaries(
    cls,
    item: dict[str, Any],
    summaries: list[dict[str, Any]],
    label: str,
) -> None:
    """Require the stored per-entry summaries and times to equal
    the summaries derived from the authenticated chains."""
    entries = item["entries"]
    if len(summaries) != len(entries):
        raise ValueError(
            f"checkpoint {label} entry count does not authenticate"
        )
    for entry, derived in zip(entries, summaries):
        if entry["summary"] != dict(derived):
            raise ValueError(
                f"checkpoint {label} summary does not authenticate "
                "its recorded diagnostic chain"
            )

@staticmethod
def _proof_audit_checkpoint_require_ordered_items(
    items: tuple[dict[str, Any], ...], label: str
) -> None:
    """Require unique-segment items to list their segment indices in
    strictly increasing chain order."""
    previous_index: int | None = None
    for item in items:
        index = item["index"]
        if previous_index is not None and index <= previous_index:
            raise ValueError(
                f"checkpoint {label} segments are not in strict "
                "chain order"
            )
        previous_index = index

