@classmethod
def _proof_audit_checkpoint_anchor_carried_hops(
    cls, view: dict[str, Any], hops: list[dict[str, Any]]
) -> None:
    """Anchor every hop boundary and unique-segment item the last
    proof's view still retains: the record must equal the
    authenticated segment/boundary, and retained item bodies are
    re-authenticated through their embedded diagnostic chains.
    Records the last proof has rotated away cannot be located and
    are left to the checksum and the hop digest chain."""
    if not view["segments"]:
        # The last proof authenticates the empty ledger: only the
        # terminal hop can reach it, and its pair boundary must be
        # the absent genesis boundary.
        if hops and hops[-1]["common"] is not None:
            raise ValueError(
                "checkpoint terminal hop boundary does not match "
                "the empty last proof"
            )
        return
    for position, hop in enumerate(hops):
        label = f"hop {position}"
        if hop["common"] is not None:
            located = (
                cls._diagnostic_ledger_proof_boundary_if_carried(
                    view, hop["common"]["index"]
                )
            )
            if located is not None and located != hop["common"]:
                raise ValueError(
                    f"checkpoint {label} boundary does not match "
                    "the last proof view"
                )
        cls._proof_audit_checkpoint_require_ordered_items(
            hop["before_only"], f"{label} before_only"
        )
        # Only the terminal anomalous hop ever carries a non-empty
        # before_only (same/continued hops leave it empty), and by
        # definition a fork/rollback/rewrite before-side cannot
        # equal the last (after) view, so it is bound by the
        # checksum and the shared boundary rather than anchored.
        cls._proof_audit_checkpoint_anchor_carried_items(
            view, hop["after_only"], f"{label} after_only"
        )

@staticmethod
def _proof_audit_checkpoint_require_ordered_items(
    items: tuple[dict[str, Any], ...], label: str
) -> None:
    """Require unique-segment items to list their segment indices in
    strictly increasing chain order."""
    previous_index: int | None = None
    for item in items:
        index = item["index"]
        if previous_index is not None and index <= previous_index:
            raise ValueError(
                f"checkpoint {label} segments are not in strict "
                "chain order"
            )
        previous_index = index

@classmethod
def _proof_audit_checkpoint_anchor_carried_items(
    cls,
    view: dict[str, Any],
    items: tuple[dict[str, Any], ...],
    label: str,
) -> None:
    """Re-authenticate one side's unique-segment items that the
    last proof still retains."""
    segments = view["segments"]
    segment_entries = view["segment_entries"]
    start = segments[0]["index"]
    end = segments[-1]["index"]
    cls._proof_audit_checkpoint_require_ordered_items(items, label)
    for item in items:
        index = item["index"]
        if not (start <= index <= end):
            # Rotated out of the last view: covered by the checksum
            # and the hop chain links, never guessed.
            continue
        offset = index - start
        meta = segments[offset]
        if item["digest"] != meta["digest"]:
            raise ValueError(
                f"checkpoint {label} digest does not match the "
                "last proof view"
            )
        expected_entries = segment_entries[offset]
        if tuple(expected_entries) != tuple(item["entries"]):
            raise ValueError(
                f"checkpoint {label} entries do not match the last "
                "proof view"
            )

@classmethod
def _proof_audit_checkpoint_verify_hop_chain(
    cls,
    status: str,
    hops: list[dict[str, Any]],
    view: dict[str, Any],
) -> None:
    """Verify the completed hops form one contiguous segment digest
    chain anchored on the last proof: a ``"continued"`` hop must
    carry exactly the contiguous segments extending its pair
    boundary (digest and cumulative entry counts included), the end
    of each hop must equal the next hop's pair boundary, and the
    chain must finish on the last proof's tail. ``"same"`` hops add
    no segment and keep the boundary; the terminal anomalous hop
    only has to be reached by the chain ending on its pair
    boundary. Segments rotated away before the last proof's own
    verified prefix boundary are covered by the checksum and the
    chain links, never guessed."""

    def end_boundary(
        hop: dict[str, Any], label: str
    ) -> dict[str, Any] | None:
        """The boundary at the end of one same/continued hop,
        rebuilt from its pair boundary and unique segments. A
        continued hop out of the empty ledger (``common`` is
        ``None``) may already carry a rotated prefix, so its first
        retained segment need not be the genesis; only internal
        contiguity is checked and the cumulative count is left to
        the view anchoring."""
        relation = hop["relation"]
        common = hop["common"]
        if relation == "same":
            if hop["after_only"]:
                raise ValueError(
                    f"checkpoint {label} same hop carries unique "
                    "segments"
                )
            return common
        if relation != "continued":
            return common
        if not hop["after_only"]:
            raise ValueError(
                f"checkpoint {label} continued hop adds no history"
            )
        if common is None:
            first_index = hop["after_only"][0]["index"]
            expected = first_index
            cumulative = 0
        else:
            expected = common["index"] + 1
            cumulative = common["entries"]
        end: dict[str, Any] | None = common
        for item in hop["after_only"]:
            if item["index"] != expected:
                raise ValueError(
                    f"checkpoint {label} unique segments are not "
                    "contiguous with its pair boundary"
                )
            cumulative += len(item["entries"])
            end = {
                "index": item["index"],
                "digest": item["digest"],
                "entries": cumulative,
            }
            expected += 1
        return end

    last_position = len(hops) - 1
    for position, hop in enumerate(hops):
        label = f"hop {position}"
        if (
            hop["relation"]
            not in
            cls._PROOF_AUDIT_CHECKPOINT_CONTINUED_RELATIONS
        ):
            if position != last_position:
                raise ValueError(
                    "a failing classification is only allowed on "
                    "the terminal hop"
                )
            continue
        end = end_boundary(hop, label)
        if position == last_position:
            if status != "continuous":
                continue
            if hop["common"] is None:
                # History growing out of the empty ledger: the last
                # proof may retain a prefix it already rotated away,
                # so its after_only must be exactly every retained
                # segment it authenticates.
                expected_items = (
                    cls._copy_diagnostic_ledger_proof_segment_items(
                        cls._diagnostic_ledger_proof_unique_segments(
                            view, None
                        )
                    )
                )
                if hop["after_only"] != expected_items:
                    raise ValueError(
                        "checkpoint hop chain does not finish on "
                        "the last proof tail"
                    )
                continue
            tail = cls._diagnostic_ledger_proof_chain_boundary(view)
            if end != tail:
                raise ValueError(
                    "checkpoint hop chain does not finish on the "
                    "last proof tail"
                )
            continue
        next_hop = hops[position + 1]
        if (
            next_hop["relation"]
            not in
            cls._PROOF_AUDIT_CHECKPOINT_CONTINUED_RELATIONS
        ):
            # The terminal anomalous hop legitimately leaves the
            # chain (a rollback ends on an earlier boundary, a fork
            # on a forked one); its own sides are anchored against
            # the last view by the caller.
            continue
        next_common = next_hop["common"]
        if hop["common"] is None:
            # Out of the empty ledger only the link index/digest can
            # be checked here; entries are anchored against the last
            # view where it still carries that segment.
            if (
                next_common is None
                or end is None
                or next_common["index"] != end["index"]
                or next_common["digest"] != end["digest"]
            ):
                raise ValueError(
                    "checkpoint hop chain is broken between adjacent "
                    "hops"
                )
        elif end != next_common:
            raise ValueError(
                "checkpoint hop chain is broken between adjacent "
                "hops"
            )

