                    item = trunk[common["index"]]
                    if item["digest"] != common["digest"]:
                        raise ValueError(
                            "checkpoint hop boundary digest does not "
                            "match the carried chain"
                        )
                elif (
                    cls._diagnostic_ledger_proof_boundary_if_carried(
                        view, common["index"]
                    )
                    is not None
                ):
                    cls._proof_audit_checkpoint_require_view_boundary(
                        view, common
                    )
    else:
        # No carried segments: every hop is "same" and each boundary
        # the last view carries must match it.
        for common in commons:
            if common is not None:
                cls._proof_audit_checkpoint_require_view_boundary(
                    view, common
                )

    terminal_hop = hops[-1]
    if (
        terminal_hop["relation"]
        not in
        cls._PROOF_AUDIT_CHECKPOINT_CONTINUED_RELATIONS
    ):
