    proof rotated history away -- straight onto its verified
    rotated-prefix boundary (digest, time bound), and otherwise
    ending on its authenticated tail. Hop pair boundaries are
    checked against the chain state at their segment. Only a prefix
    the last proof itself remembers solely in aggregate (and the
    fork/rollback leg of the terminal anomalous hop, chained from
    the shared boundary) lies outside this anchoring. Any
    contradiction raises :class:`ValueError`."""
    segments = view["segments"]
    retained = {
        meta["index"]: (meta, view["segment_entries"][position])
        for position, meta in enumerate(segments)
    }
    dropped = view["dropped"]
    terminal_position = len(hops) - 1

    trunk: dict[int, dict[str, Any]] = {}
    for position, hop in enumerate(hops):
        label = f"hop {position}"
        cls._proof_audit_checkpoint_require_ordered_items(
            hop["before_only"], f"{label} before_only"
        )
        cls._proof_audit_checkpoint_require_ordered_items(
            hop["after_only"], f"{label} after_only"
        )
        terminal_failed = (
            position == terminal_position
            and hop["relation"]
            not in
            cls._PROOF_AUDIT_CHECKPOINT_CONTINUED_RELATIONS
        )
        if terminal_failed:
            continue
        if hop["relation"] == "continued" and not hop["after_only"]:
            raise ValueError(
                f"checkpoint {label} continued hop adds no history"
            )
        for item in hop["after_only"]:
            index = item["index"]
            if index in trunk:
                raise ValueError(
                    f"checkpoint {label} repeats a carried segment"
                )
            trunk[index] = item

    expected_boundaries: dict[int, dict[str, Any]] = {}
    for hop in hops:
        common = hop["common"]
        if common is None:
            continue
        existing = expected_boundaries.get(common["index"])
        if existing is not None and existing != common:
            raise ValueError(
                "checkpoint hop boundaries disagree at one segment"
            )
        expected_boundaries[common["index"]] = common

    if trunk:
        indices = sorted(trunk)
        first_common = hops[0]["common"]
        if first_common is None:
            # Growing out of the empty ledger: the first carried
            # segment may sit behind an aggregate rotated prefix no
            # proof in the sequence retained, so its predecessor
            # digest alone cannot be anchored here.
            previous_digest: str | None = None
            cumulative_entries: int | None = None
        else:
            if indices[0] != first_common["index"] + 1:
                raise ValueError(
                    "checkpoint hop history does not start at the "
                    "first hop boundary"
                )
            previous_digest = first_common["digest"]
            cumulative_entries = first_common["entries"]
        expected_index = indices[0]
        last_item: dict[str, Any] | None = None
        for index in indices:
            item = trunk[index]
            if index != expected_index:
                raise ValueError(
                    "checkpoint carried history has a gap or overlap"
                )
            label = f"carried segment {index}"
            if previous_digest is None:
                cls._proof_audit_checkpoint_authenticate_item_bodies(
                    item, label
                )
            else:
                cls._proof_audit_checkpoint_authenticate_item(
                    item, previous_digest, label
                )
            cumulative_entries = (
                len(item["entries"])
                if cumulative_entries is None
                else cumulative_entries + len(item["entries"])
            )
            if index in retained:
                meta, entries = retained[index]
                if item["digest"] != meta["digest"]:
                    raise ValueError(
                        f"checkpoint {label} digest does not match "
                        "the last proof view"
                    )
                if tuple(item["entries"]) != tuple(entries):
                    raise ValueError(
                        f"checkpoint {label} entries do not match "
                        "the last proof view"
                    )
            boundary = expected_boundaries.get(index)
            if boundary is not None:
                if boundary["digest"] != item["digest"]:
                    raise ValueError(
                        f"checkpoint {label} boundary digest does "
                        "not match the carried chain"
                    )
                if (
                    cumulative_entries is not None
                    and boundary["entries"] != cumulative_entries
                ):
                    raise ValueError(
                        f"checkpoint {label} boundary entry count "
                        "does not match the carried chain"
                    )
            previous_digest = item["digest"]
            last_item = item
            expected_index += 1
