    recorded entries: its SHA-256 digest is recomputed, its
    predecessor link chained and its embedded diagnostic chains and
    summaries re-authenticated. A carried segment the last proof
    directly retains (or which is its verified rotated-prefix
    boundary) must equal that proof's record. The successful hops'
    unique segments form one contiguous trunk -- continued hops
    only ever extend the previous proof's tail, so rotations never
    gap it -- ending, for a continuous audit, on the last proof's
    authenticated tail; hop pair boundaries sit on that trunk. The
    terminal anomalous hop's non-trunk leg (a fork's left history
    or a rollback's removed history) is chained from the shared
    pair boundary the same way. The sole unanchored point is the
    predecessor of the first segment behind a rotated prefix the
    last proof only remembers in aggregate, and the chain is
    anchored again at that proof's verified prefix boundary. Any
    contradiction raises :class:`ValueError`."""
    segments = view["segments"]
    retained = {
        meta["index"]: (meta, view["segment_entries"][position])
        for position, meta in enumerate(segments)
    }
    dropped = view["dropped"]
    dropped_index = (
        segments[0]["index"] - 1 if segments and dropped else None
    )
    terminal_position = len(hops) - 1

    trunk: dict[int, dict[str, Any]] = {}
    for position, hop in enumerate(hops):
        label = f"hop {position}"
        cls._proof_audit_checkpoint_require_ordered_items(
            hop["before_only"], f"{label} before_only"
        )
        cls._proof_audit_checkpoint_require_ordered_items(
            hop["after_only"], f"{label} after_only"
        )
        terminal_failed = (
            position == terminal_position
            and hop["relation"]
            not in
            cls._PROOF_AUDIT_CHECKPOINT_CONTINUED_RELATIONS
        )
        if terminal_failed:
            continue
        if hop["relation"] == "same":
            if hop["after_only"]:
                raise ValueError(
                    f"checkpoint {label} same hop carries unique "
                    "segments"
                )
            continue
        if not hop["after_only"]:
            raise ValueError(
                f"checkpoint {label} continued hop adds no history"
            )
        for item in hop["after_only"]:
            index = item["index"]
            if index in trunk:
                raise ValueError(
                    f"checkpoint {label} repeats a carried segment"
                )
            trunk[index] = item

    boundaries: dict[int, dict[str, Any]] = {}
    for hop in hops:
        common = hop["common"]
        if common is None:
            continue
        existing = boundaries.get(common["index"])
        if existing is not None and existing != common:
            raise ValueError(
                "checkpoint hop boundaries disagree at one segment"
            )
        boundaries[common["index"]] = common

    def anchor_boundary(index: int, digest: str, entries: int,
                       label: str) -> None:
        recorded = boundaries.get(index)
        if recorded is not None and (
            recorded["digest"] != digest
            or recorded["entries"] != entries
        ):
            raise ValueError(
                f"checkpoint {label} does not match a recorded hop "
                "boundary"
            )

