@classmethod
def _proof_audit_checkpoint_verify_rotations(
    cls,
    last_auth: dict[str, Any],
    hops: list[dict[str, Any]],
    trunk: dict[int, dict[str, Any]],
    status: str,
) -> None:
    """Anchor every continued hop's newly rotated identities.

    A continued hop that rotates drops a contiguous prefix
    window, so the identities it newly rotates are exactly the
    transactions of a run of segments ending no later than the
    hop's pair boundary. Those segments are authenticated two
    complementary ways:

    * a segment the checkpoint carries as a hop increment is in
      the trunk, so its identities are required to equal the
      window's rebuilt entries, run by contiguous run;
    * the earliest rotated segments may belong to the first
      proof's own pre-sequence history, which never entered a hop
      increment; those identities must instead form exactly the
      first ``k`` entries, in order, of the last proof's
      authenticated prefix evidence.

    Rotation is permanent: identities are distinct within and
    across hops, the unlocated identities precede every located
    one, windows never overlap or move backwards, and a rotated
    identity never reappears in later retained history. Any
    contradiction raises :class:`ValueError`."""
    requested = set(last_auth["mode"]["transactions"])
    cumulative_evidence = tuple(last_auth["view"]["evidence"])
    transactions_by_index = (
        cls._proof_audit_checkpoint_trunk_transactions(trunk)
    )
    identity_index = {
        identity: index
        for index, identities in transactions_by_index.items()
        for identity in identities
    }
    seen: set[str] = set()
    unlocated: list[str] = []
    window_end = 0
    for position, hop in enumerate(hops):
        if hop["relation"] != "continued":
            continue
        rotated = tuple(hop["rotated"])
        if len(set(rotated)) != len(rotated):
            raise ValueError(
                f"checkpoint hop {position} rotates a repeated "
                "identity"
            )
        if set(rotated) - requested:
            raise ValueError(
                f"checkpoint hop {position} rotates an identity "
                "outside the requested set"
            )
        if set(rotated) & seen:
            raise ValueError(
                f"checkpoint hop {position} rotates an identity an "
                "earlier hop already rotated away"
            )
        located_pairs: list[tuple[int, str]] = []
        hop_unlocated: list[str] = []
        for identity in rotated:
            index = identity_index.get(identity)
            if index is None:
                if located_pairs:
                    raise ValueError(
                        f"checkpoint hop {position} rotates an "
                        "unlocated identity after a located one"
                    )
                hop_unlocated.append(identity)
            else:
                located_pairs.append((index, identity))
        if hop_unlocated:
            unlocated.extend(hop_unlocated)
        if located_pairs:
            indices = [index for index, _identity in located_pairs]
            start = indices[0]
            end = indices[-1]
            if start <= window_end:
                raise ValueError(
                    f"checkpoint hop {position} rotation window "
                    "overlaps an earlier rotation"
                )
            if end > hop["common"]["index"]:
                raise ValueError(
                    f"checkpoint hop {position} rotates a segment "
                    "past its pair boundary"
                )
            if indices != list(range(start, end + 1)):
                raise ValueError(
                    f"checkpoint hop {position} rotation window is "
                    "not contiguous"
                )
            expected: list[str] = []
            for index in range(start, end + 1):
                item = trunk.get(index)
                if item is None:
                    raise ValueError(
                        f"checkpoint hop {position} rotation window "
                        "names a segment the history does not carry"
                    )
                expected.extend(
                    entry["summary"]["transaction"]
                    for entry in item["entries"]
                )
            if [identity for _index, identity in located_pairs] \
                    != expected:
                raise ValueError(
                    f"checkpoint hop {position} rotated identities "
                    "do not match the rotated segments' entries"
                )
            window_end = end
        common_index = hop["common"]["index"]
        for identity in rotated:
            index = identity_index.get(identity)
            if index is not None and index > common_index:
                raise ValueError(
                    f"checkpoint hop {position} rotates an identity "
                    "that reappears in later retained history"
                )
        seen.update(rotated)
    if tuple(unlocated) != cumulative_evidence[: len(unlocated)]:
        raise ValueError(
            "checkpoint rotated identities do not match the last "
            "proof's authenticated prefix evidence"
        )
    if len(unlocated) > len(cumulative_evidence):
        raise ValueError(
            "checkpoint rotates more unlocated identities than the "
            "last proof's prefix evidence remembers"
        )

