    def expected_window(
        previous_count: int, boundary_count: int
    ) -> tuple[list[str], int]:
        """The requested identities with a global position in the
        inclusive window, in request order, and how many window
        positions the last proof actually remembers."""
        covered = ordered_prefix[
            previous_count:boundary_count
        ]
        covered_set = set(covered)
        return (
            [
                identity
                for identity in requested
                if identity in covered_set
            ],
            covered_count(previous_count, boundary_count),
        )

    def covered_count(previous_count: int, boundary_count: int) -> int:
        if boundary_count <= remembered:
            return boundary_count - previous_count
        return max(0, remembered - previous_count)

    for position, hop in enumerate(hops):
